# IAM Configuration for federated_console_takeover scenario

# Initial user with limited permissions
resource "aws_iam_user" "initial_user" {
  name = "cg-initial-user-${var.cgid}"

  tags = {
    Name = "cg-initial-user-${var.cgid}"
  }
}

resource "aws_iam_access_key" "initial_user" {
  user = aws_iam_user.initial_user.name
}

resource "aws_iam_user_policy" "initial_user_policy" {
  name = "cg-initial-user-policy-${var.cgid}"
  user = aws_iam_user.initial_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeIamInstanceProfileAssociations",
          "iam:ListRoles",
          "ssm:StartSession",
          "sts:GetCallerIdentity"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:TerminateSession"
        ]
        Resource = "arn:aws:ssm:*:*:session/$${aws:username}-*"
      }
    ]
  })
}

# EC2 Admin Role with elevated permissions
resource "aws_iam_role" "ec2_admin_role" {
  name = "cg-ec2-admin-role-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "cg-ec2-admin-role-${var.cgid}"
  }
}

# EC2 Admin Role Policy
resource "aws_iam_role_policy" "ec2_admin_policy" {
  name = "cg-ec2-admin-policy-${var.cgid}"
  role = aws_iam_role.ec2_admin_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:ListUsers",
          "iam:GetUser",
          "ec2:*",
          "ssm:GetParameter*",
          "ssm:DescribeParameters"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach the EC2 Role to an Instance Profile
resource "aws_iam_instance_profile" "ec2_admin_profile" {
  name = "cg-ec2-admin-profile-${var.cgid}"
  role = aws_iam_role.ec2_admin_role.name
}

# SSM Role Policy (allowing EC2 to communicate with SSM)
resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_admin_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

## Output Configuration for federated_console_takeover scenario

# Initial access credentials
output "initial_access_key_id" {
  value = aws_iam_access_key.initial_user.id
}

output "initial_access_key_secret" {
  value     = aws_iam_access_key.initial_user.secret
  sensitive = true
}


# Scenario instructions
output "cloudgoat_output_message" {
  value = <<EOT

========================[ federated_console_takeover ]========================

INITIAL ACCESS:
  AWS Access Key ID: ${aws_iam_access_key.initial_user.id}
  AWS Secret Key: ${aws_iam_access_key.initial_user.secret}
  Region: ${var.region}

SCENARIO OBJECTIVE:
  Pivot from limited AWS CLI access to AWS Management Console 
  with elevated permissions through IMDSv2 exploitation.

========================[ Good luck and happy hacking! ]========================

EOT
  sensitive = true
}

# AWS Provider Configuration for federated_console_takeover scenario
# Configure required Terraform and provider versions.

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.74.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

# SSM Configuration for federated_console_takeover scenario

# SSM Document for Session Manager customization
resource "aws_ssm_document" "session_manager_preferences" {
  name            = "cg-ssm-preferences-${var.cgid}"
  document_type   = "Session"
  document_format = "JSON"

  content = jsonencode({
    schemaVersion = "1.0"
    description   = "Document to customize Session Manager preferences"
    sessionType   = "Standard_Stream"
    inputs = {
      s3BucketName                = ""
      s3KeyPrefix                 = ""
      s3EncryptionEnabled         = true
      cloudWatchLogGroupName      = ""
      cloudWatchEncryptionEnabled = true
      idleSessionTimeout          = "20"
      shellProfile = {
        linux = "echo 'Welcome to the CloudGoat federated_console_takeover scenario!'\necho 'Try exploring the instance metadata service...'"
      }
    }
  })
}

## Variables for federated_console_takeover scenario

variable "profile" {
  description = "The AWS profile to use when deploying resources"
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources into"
  default     = "us-east-1"
  type        = string

  validation {
    condition     = can(regex("^(us-east-1|us-west-1|us-west-2|eu-west-1|eu-central-1)$", var.region))
    error_message = "The region must be a valid AWS region where all required services are available."
  }
}

variable "cgid" {
  description = "CGID variable for unique naming between scenarios"
  type        = string

  validation {
    condition     = can(regex("^[a-z0-9]{6,20}$", var.cgid))
    error_message = "The cgid must be 6-20 lowercase alphanumeric characters."
  }
}

variable "cg_whitelist" {
  description = "User's public IP address(es) for restricting access to resources"
  type        = list(string)
}

# VPC and networking variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
  type        = string
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
  type        = string
}

# EC2 variables
variable "ec2_instance_type" {
  description = "Instance type for EC2 instance"
  default     = "t3.micro"
  type        = string

  validation {
    condition     = contains(["t3.micro", "t3.small", "t4g.micro"], var.ec2_instance_type)
    error_message = "The instance type must be small to stay within free tier limits."
  }
}

# Stack naming variables required by CloudGoat
variable "stack-name" {
  description = "Name of the stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario being deployed"
  default     = "federated_console_takeover"
  type        = string
}

# VPC Configuration for federated_console_takeover scenario

resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true  # Required for VPC endpoints with private DNS
  enable_dns_hostnames = true  # Required for VPC endpoints with private DNS

  tags = {
    Name = "cg-vpc-${var.cgid}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = "cg-igw-${var.cgid}"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = var.subnet_cidr
  availability_zone       = "${var.region}a"
  map_public_ip_on_launch = true

  tags = {
    Name = "cg-subnet-${var.cgid}"
  }
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = "cg-route-table-${var.cgid}"
  }
}

resource "aws_route" "route" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "route_table_association" {
  subnet_id      = aws_subnet.subnet.id
  route_table_id = aws_route_table.route_table.id
}

# VPC Endpoint for SSM
resource "aws_vpc_endpoint" "ssm" {
  vpc_id            = aws_vpc.vpc.id
  service_name      = "com.amazonaws.${var.region}.ssm"
  vpc_endpoint_type = "Interface"
  subnet_ids        = [aws_subnet.subnet.id]

  security_group_ids = [
    aws_security_group.vpc_endpoint_sg.id
  ]

  private_dns_enabled = true

  tags = {
    Name = "cg-ssm-endpoint-${var.cgid}"
  }
}

# VPC Endpoint for SSM Messages
resource "aws_vpc_endpoint" "ssm_messages" {
  vpc_id            = aws_vpc.vpc.id
  service_name      = "com.amazonaws.${var.region}.ssmmessages"
  vpc_endpoint_type = "Interface"
  subnet_ids        = [aws_subnet.subnet.id]

  security_group_ids = [
    aws_security_group.vpc_endpoint_sg.id
  ]

  private_dns_enabled = true

  tags = {
    Name = "cg-ssm-messages-endpoint-${var.cgid}"
  }
}

# VPC Endpoint for EC2 Messages
resource "aws_vpc_endpoint" "ec2_messages" {
  vpc_id            = aws_vpc.vpc.id
  service_name      = "com.amazonaws.${var.region}.ec2messages"
  vpc_endpoint_type = "Interface"
  subnet_ids        = [aws_subnet.subnet.id]

  security_group_ids = [
    aws_security_group.vpc_endpoint_sg.id
  ]

  private_dns_enabled = true

  tags = {
    Name = "cg-ec2-messages-endpoint-${var.cgid}"
  }
}

# Security Group for VPC Endpoints
resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "cg-vpc-endpoint-sg-${var.cgid}"
  description = "Allow TLS inbound traffic for VPC endpoints"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cg-vpc-endpoint-sg-${var.cgid}"
  }
}
